{
  "claims": [
    {
      "claim": "Direct human data list cefadroxil, the query molecule, among oral cephalosporins with absolute oral bioavailability greater than 90%, strongly supporting F>=20%.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 1"],
      "record_ids": ["Record 1-4"]
    },
    {
      "claim": "Cephradine, a close structural analog differing mainly in the cyclohexadienyl versus p-hydroxyphenyl side chain, has mean human absolute oral bioavailability of about 85-100%, including ~94% in young and elderly subjects and complete absorption from oral dosage forms.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 1", "Molecule 6"],
      "record_ids": ["Record 1-1", "Record 1-2", "Record 1-3", "Record 1-5", "Record 6-1"]
    },
    {
      "claim": "Amoxicillin, which shares the p-hydroxyphenylglycyl amino-acid side chain and zwitterionic beta-lactam character, shows human absolute oral bioavailability values mostly 55-93%, with many healthy-subject estimates of 77-93%, all well above the 20% threshold.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 3", "Molecule 4"],
      "record_ids": ["Record 3-1", "Record 3-2", "Record 3-3", "Record 4-1", "Record 4-2", "Record 4-3", "Record 4-6", "Record 4-7", "Record 4-8", "Record 4-9", "Record 4-10"]
    },
    {
      "claim": "Ampicillin, the phenylglycine analog without the p-hydroxy group, has human oral bioavailability values around 29-62% across multiple studies, still above the 20% threshold.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 9", "Molecule 10"],
      "record_ids": ["Record 9-1", "Record 10-1", "Record 10-2", "Record 10-3", "Record 10-4", "Record 10-5", "Record 10-6", "Record 10-7", "Record 10-8", "Record 10-9", "Record 10-10"]
    },
    {
      "claim": "Other orally administered cephalosporins support a high absorption classification: cefroxadine is nearly 100% bioavailable in humans, and cefoperazone is reported as 40% orally bioavailable in humans.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 5", "Molecule 8"],
      "record_ids": ["Record 5-1", "Record 8-1"]
    },
    {
      "claim": "Mechanistic transporter data show cephalexin and related beta-lactams are PEPT1 substrates with high human intestinal absorption and effective carrier-mediated permeability despite low passive permeability; the query's amino-acid amide side chain is expected to use the same absorptive route.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 11", "Molecule 13"],
      "record_ids": ["Record 11-15", "Record 11-17", "Record 11-28", "Record 11-29", "Record 11-46", "Record 13-1"]
    },
    {
      "claim": "Fail-direction bioavailability values exist for cefazolin (1.5-2%), oral ceftriaxone (8%), and cephalexin in horses or under drug-interaction/rat conditions (~5-19%), but these involve parenteral or structurally distant cephalosporins, non-human species, or atypical conditions, so their transferability to human oral cefadroxil is very limited.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 2", "Molecule 7", "Molecule 11"],
      "record_ids": ["Record 2-1", "Record 7-1", "Record 11-2", "Record 11-3", "Record 11-7", "Record 11-9"]
    }
  ],
  "final_prediction": "pass"
}
